// Package lalr_logicparser provides an LALR(1) formula parser generated by
// goyacc, mechanically translated from the Python PLY grammar. It is used
// as a cross-validation oracle for the hand-written recursive descent parser.
package goivy

import (
	"fmt"
)

// ParseLogic dispatches to the appropriate version-specific LALR parser.
func ParseLogic(input string, version Version, cfg ...*AstConfig) (Node, error) {
	var c *AstConfig
	if len(cfg) > 0 {
		c = cfg[0]
	}
	if version[0] < 1 || (version[0] == 1 && version[1] <= 2) {
		return ParseV12(input, version, c)
	}
	if version[0] == 1 && version[1] <= 6 {
		return ParseV16(input, version, c)
	}
	return ParseLogicV17(input, version, c)
}

// ParseLogicTerm dispatches to the appropriate version-specific term parser.
func ParseLogicTerm(input string, version Version, cfg ...*AstConfig) (Node, error) {
	var c *AstConfig
	if len(cfg) > 0 {
		c = cfg[0]
	}
	if version[0] < 1 || (version[0] == 1 && version[1] <= 2) {
		return ParseV12(input, version, c)
	}
	if version[0] == 1 && version[1] <= 6 {
		return ParseV16Term(input, version, c)
	}
	return ParseLogicV17(input, version, c)
}

// ParseLogicV17 parses a formula string using the v1.7+ LALR grammar.
// Returns the AST node, or an error if parsing fails.
func ParseLogicV17(input string, version Version, cfg ...*AstConfig) (Node, error) {
	var c *AstConfig
	if len(cfg) > 0 {
		c = cfg[0]
	}
	lex := newLalr17LexAdapter(input, version, c)
	lalr17Parse(lex)
	if lex.err != "" {
		return nil, fmt.Errorf("LALR parse error: %s", lex.err)
	}
	return lex.result, nil
}

// --- lalr17LexAdapter: adapter from lexer.Lexer to goyacc's lalr17Lexer interface ---

// lalr17LexAdapter implements the lalr17Lexer interface generated by goyacc.
type lalr17LexAdapter struct {
	lex    *Lexer
	cfg    *AstConfig
	result Node
	err    string
}

func newLalr17LexAdapter(input string, version Version, cfg *AstConfig) *lalr17LexAdapter {
	if cfg == nil {
		cfg = NewAstConfig()
	}
	return &lalr17LexAdapter{
		lex: NewLexer(input, version),
		cfg: cfg,
	}
}

// Lex returns the next token for goyacc.
func (l *lalr17LexAdapter) Lex(lval *lalr17SymType) int {
	tok := l.lex.NextToken()

	switch tok.Type {
	case EOF:
		return 0
	case SYMBOL:
		lval.str = tok.Value
		return LALR17_TOK_PRESYMBOL
	case VARIABLE:
		lval.str = tok.Value
		return LALR17_TOK_VARIABLE
	case LPAREN:
		return LALR17_TOK_LPAREN
	case RPAREN:
		return LALR17_TOK_RPAREN
	case LB:
		return LALR17_TOK_LB
	case RB:
		return LALR17_TOK_RB
	case LCB:
		return LALR17_TOK_LCB
	case RCB:
		return LALR17_TOK_RCB
	case COMMA:
		return LALR17_TOK_COMMA
	case SEMI:
		return LALR17_TOK_SEMI
	case COLON:
		return LALR17_TOK_COLON
	case DOT:
		return LALR17_TOK_DOT
	case PLUS:
		return LALR17_TOK_PLUS
	case MINUS:
		return LALR17_TOK_MINUS
	case TIMES:
		return LALR17_TOK_TIMES
	case DIV:
		return LALR17_TOK_DIV
	case EQ:
		return LALR17_TOK_EQ
	case TILDAEQ:
		return LALR17_TOK_TILDAEQ
	case TILDA:
		return LALR17_TOK_TILDA
	case LE:
		return LALR17_TOK_LE
	case LT:
		return LALR17_TOK_LT
	case GE:
		return LALR17_TOK_GE
	case GT:
		return LALR17_TOK_GT
	case AND:
		return LALR17_TOK_AND
	case OR:
		return LALR17_TOK_OR
	case ARROW:
		return LALR17_TOK_ARROW
	case IFF:
		return LALR17_TOK_IFF
	case PTO:
		return LALR17_TOK_PTO
	case DOLLAR:
		return LALR17_TOK_DOLLAR
	case FORALL:
		return LALR17_TOK_FORALL
	case EXISTS:
		return LALR17_TOK_EXISTS
	case TRUE:
		return LALR17_TOK_TRUE
	case FALSE:
		return LALR17_TOK_FALSE
	case OLD:
		return LALR17_TOK_OLD
	case THIS:
		return LALR17_TOK_THIS
	case ISA:
		return LALR17_TOK_ISA
	case IF:
		return LALR17_TOK_IF
	case ELSE:
		return LALR17_TOK_ELSE
	case GLOBALLY:
		return LALR17_TOK_GLOBALLY
	case EVENTUALLY:
		return LALR17_TOK_EVENTUALLY
	case WHENNEXT:
		return LALR17_TOK_WHENNEXT
	case WHENPREV:
		return LALR17_TOK_WHENPREV
	case WHENFIRST:
		return LALR17_TOK_WHENFIRST
	case WHENLAST:
		return LALR17_TOK_WHENLAST
	// Action tokens
	case ASSUME:
		return LALR17_TOK_ASSUME
	case ASSERT:
		return LALR17_TOK_ASSERT
	case REQUIRE:
		return LALR17_TOK_REQUIRE
	case ENSURE:
		return LALR17_TOK_ENSURE
	case ASSIGN:
		return LALR17_TOK_ASSIGN
	case VAR:
		return LALR17_TOK_VAR
	case LOCAL:
		return LALR17_TOK_LOCAL
	case LET:
		return LALR17_TOK_LET
	case CALL:
		return LALR17_TOK_CALL
	case WHILE:
		return LALR17_TOK_WHILE
	case FOR:
		return LALR17_TOK_FOR
	case IN:
		return LALR17_TOK_IN
	case INVARIANT:
		return LALR17_TOK_INVARIANT
	case DECREASES:
		return LALR17_TOK_DECREASES
	case RETURNS:
		return LALR17_TOK_RETURNS
	case SOME:
		return LALR17_TOK_SOME
	case MINIMIZING:
		return LALR17_TOK_MINIMIZING
	case MAXIMIZING:
		return LALR17_TOK_MAXIMIZING
	case DEBUG:
		return LALR17_TOK_DEBUG
	case THUNK:
		return LALR17_TOK_THUNK
	case UNPROVABLE:
		return LALR17_TOK_UNPROVABLE
	case PROOF:
		return LALR17_TOK_PROOF
	case INSTANTIATE:
		return LALR17_TOK_INSTANTIATE
	case CARET:
		return LALR17_TOK_CARET
	case METHOD:
		return LALR17_TOK_METHOD
	case NULL:
		return LALR17_TOK_NULL
	case SET:
		return LALR17_TOK_SET
	case WITH:
		return LALR17_TOK_WITH
	// Proof/tactic tokens
	case TACTIC:
		return LALR17_TOK_TACTIC
	case DEFINITION:
		return LALR17_TOK_DEFINITION
	case TRIGGER:
		return LALR17_TOK_TRIGGER
	case SHOWGOALS:
		return LALR17_TOK_SHOWGOALS
	case DEFERGOAL:
		return LALR17_TOK_DEFERGOAL
	case SPOIL:
		return LALR17_TOK_SPOIL
	case UNFOLD:
		return LALR17_TOK_UNFOLD
	case FORGET:
		return LALR17_TOK_FORGET
	case PROPERTY:
		return LALR17_TOK_PROPERTY
	case FUNCTION:
		return LALR17_TOK_FUNCTION
	case THEOREM:
		return LALR17_TOK_THEOREM
	case APPLY:
		return LALR17_TOK_APPLY
	// Scenario tokens
	case SCENARIO:
		return LALR17_TOK_SCENARIO
	case BEFORE:
		return LALR17_TOK_BEFORE
	case AFTER:
		return LALR17_TOK_AFTER
	default:
		lval.str = tok.Value
		return LALR17_TOK_PRESYMBOL
	}
}

// Error is called by goyacc when a parse error occurs.
func (l *lalr17LexAdapter) Error(s string) {
	l.err = s
}
